# file_stats_tool.py

import os
from datetime import datetime
from typing import Dict, Any
import json

async def _read_file_metadata(path: str) -> Dict[str, Any]:
    """Reads metadata of a file."""
    try:
        stats = os.stat(path)
        return {
            "size_bytes": stats.st_size,
            "last_modified": datetime.fromtimestamp(stats.st_mtime).isoformat()
        }
    except FileNotFoundError:
        return {"error": f"File not found: {path}"}
    except NotADirectoryError:
        return {"error": f"Not a file: {path}"}

async def _build_file_stats(path: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
    """Builds the result dictionary for file stats."""
    if "error" in metadata:
        return metadata

    _, ext = os.path.splitext(path)
    line_count = sum(1 for _ in open(path, 'r', encoding='utf-8'))

    return {
        "path": path,
        **metadata,
        "line_count": line_count,
        "extension": ext
    }

async def file_stats(path: str) -> Dict[str, Any]:
    """
    Returns statistics about a file.

    Parameters:
    - path (str): Absolute or relative path to a file.
    """
    metadata = await _read_file_metadata(path)
    return await _build_file_stats(path, metadata)

# directory_summary_tool.py

import os
from typing import Dict, Any
import json

async def _read_directory_entries(path: str) -> Dict[str, Any]:
    """Reads entries of a directory."""
    try:
        with os.scandir(path) as entries:
            return {"entries": list(entries)}
    except FileNotFoundError:
        return {"error": f"Directory not found: {path}"}
    except NotADirectoryError:
        return {"error": f"Not a directory: {path}"}

async def _build_directory_summary(entries: Any, extension_filter: str = None) -> Dict[str, Any]:
    """Builds the result dictionary for directory summary."""
    if "error" in entries:
        return entries

    file_count = 0
    total_bytes = 0
    extensions = {}

    for entry in entries["entries"]:
        if entry.is_file():
            _, ext = os.path.splitext(entry.name)
            extensions[ext] = extensions.get(ext, 0) + 1

            if extension_filter is None or ext == extension_filter:
                file_count += 1
                total_bytes += entry.stat().st_size

    return {
        "file_count": file_count,
        "total_bytes": total_bytes,
        "extensions": extensions
    }

async def directory_summary(path: str, extension: str = "") -> Dict[str, Any]:
    """
    Returns a summary of a directory.

    Parameters:
    - path (str): Path to a directory.
    - extension (str, optional): Extension to filter files by (e.g., ".py").
    """
    entries = await _read_directory_entries(path)
    return await _build_directory_summary(entries, extension)

