from fastmcp import MCP
import file_stats_tool
import directory_summary_tool

async def handle_request(tool: str, params: Dict[str, Any]) -> Dict[str, Any]:
    """Handles incoming requests and dispatches them to the appropriate tool."""
    if tool == "file_stats":
        return await file_stats_tool.file_stats(**params)
    elif tool == "directory_summary":
        return await directory_summary_tool.directory_summary(**params)
    else:
        return {"error": f"Unknown tool: {tool}"}

if __name__ == "__main__":
    mcp = MCP(handle_request, transport="stdio")
    mcp.run()
